module top_module(
    input clk,
    input rst,
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient
);reg [15:0] remainder;
reg [3:0] count;

always @(posedge clk) begin
    if (rst) begin
        quotient <= 0;
        remainder <= 0;
        count <= 0;
    end else begin
        if (count == 0) begin
            remainder <= dividend;
            count <= 16;
        end else begin
            remainder <= {remainder, 1'b0};
            count <= count - 1;
            if (remainder >= divisor) begin
                remainder <= remainder - divisor;
                quotient[count - 1] <= 1'b1;
            end else begin
                quotient[count - 1] <= 1'b0;
            end
        end
    end
end

endmodule

