description:
Design a module that implements a Pulse Width Modulation (PWM) LED driver capable of controlling multiple LED outputs based on an input data signal. The module takes an n-bit data input and drives m LED outputs, where each LED’s brightness level corresponds to a PWM signal generated from the input data. It utilizes a counter to manage the PWM period and dynamically adjusts the duty cycle for each LED, allowing for varied brightness control. The output LEDs are turned on or off depending on whether the respective input data value exceeds the current duty cycle value, creating a smooth and adjustable lighting effect.
module top_module(
  input [n-1:0] data,
  output reg [m-1:0] led,
  input clk // Added clk input
);

code:
module top_module(
  input [n-1:0] data,
  output reg [m-1:0] led,
  input clk // Added clk input
);parameter n = 8; // number of bits in data
parameter m = 4; // number of LED lights

// define PWM parameters
parameter T = 100; // PWM period (in clock cycles)
parameter D_max = 2**n - 1; // maximum duty cycle (i.e., maximum brightness)

// define internal counters
reg [n-1:0] count;
reg [n-1:0] duty [0:m-1]; // Changed to array declaration for duty
integer i; // Declare index variable

// initialize counters
initial begin
  count = 0;
  for (i = 0; i < m; i = i + 1) begin
    duty[i] = 0; // Initialize the duty cycle array
  end
end

// generate PWM pulses
always @ (posedge clk) begin
  if (count == T - 1) begin // Changed condition to T-1 for proper frequency
    count <= 0;
  end else begin
    count <= count + 1;
  end

  // Update LED output based on duty cycle
  for (i = 0; i < m; i = i + 1) begin
    if (count < duty[i]) begin // Compare count with duty cycle
      led[i] <= 1;
    end else begin
      led[i] <= 0;
    end
  end

  // Update duty cycle
  for (i = 0; i < m; i = i + 1) begin
    if (duty[i] < D_max) begin
      duty[i] <= duty[i] + 1;
    end else begin
      duty[i] <= 0;
    end
  end
end

endmodule

