module top_module( clk,rst,	
					en_ma21,    
					coef0,      
					masked_in,  
					ma18_in,	
					ma21_out    
    );input clk,rst;	
input en_ma21;   
input [20:0] coef0;      
input [14:0] masked_in;  
input [17:0] ma18_in;  
output signed [15:0] ma21_out;       

reg signed [14:0] mask_signed;
reg signed [35:0] m1_temp;
reg signed [17:0] ma18_signed;
reg signed [36:0] ma21_signed;
reg signed [20:0] c0_signed;

always@(posedge clk)
	if(rst | ~en_ma21)
		begin 
			ma21_signed<=37'd0;
			m1_temp<=36'd0;
		end
	else
		begin
			mask_signed<=masked_in;
			c0_signed<=coef0;
			ma18_signed<=ma18_in;
			m1_temp<=mask_signed * ma18_signed;
			ma21_signed<=m1_temp+c0_signed;
		end

assign ma21_out = ma21_signed[36:21];

endmodule

