module top_module(
  input                clk,
  input                rst_n,
  output reg  [31:0]   Q
);reg [31:0] lfsr_reg;
  reg [31:0] lfsr_next;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      lfsr_reg <= 32'h00000001;
      Q <= 4'b0001;
    end
    else begin
      lfsr_reg <= lfsr_next;
      Q <= lfsr_reg[3:0];
    end
  end

  assign lfsr_next[31:1] = lfsr_reg[30:0];
  assign lfsr_next[0] = lfsr_reg[31] ^ lfsr_reg[28];

endmodule

