description:
Design a clock divider that generates two output signals, Y and Z, based on the input clock signal X. The output Y goes HIGH for one clock cycle every 10 clock pulses received on X, while output Z goes HIGH for one clock cycle every 20 clock pulses. This module effectively divides the frequency of the input clock signal, creating two distinct slower clock signals for timing purposes in other circuit components.
module top_module(
    output reg Y,  // Changed to output reg to allow assignment in always block
    output reg Z,  // Changed to output reg to allow assignment in always block
    input X
);

code:
module top_module(
    output reg Y,  // Changed to output reg to allow assignment in always block
    output reg Z,  // Changed to output reg to allow assignment in always block
    input X
);reg [31:0] counter_1;
    reg [31:0] counter_2;

    always @(posedge X) begin
        counter_1 <= counter_1 + 1;
        counter_2 <= counter_2 + 1;

        if (counter_1 == 10) begin
            Y <= 1;
            counter_1 <= 0;
        end else begin
            Y <= 0;
        end

        if (counter_2 == 20) begin
            Z <= 1;
            counter_2 <= 0;
        end else begin
            Z <= 0;
        end
    end

endmodule

