    if( !reset )
    begin
        weight_num <= 0;
        cnt <= 0;
    end
    else
    begin
        if(pool_read_en)
        begin
            if((weight_num == 9) && (cnt == 27))
            begin
                weight_num <= 0;
                cnt <= 0;
            end
            else if(cnt == 27)
            begin
                weight_num <= weight_num +1;
                cnt <=0;
            end
            else
            begin
                cnt <= cnt + 1;
            end
        end
        else
        begin
            weight_num <= 0;
            cnt <= 0;
        end
    end
end
endmodule

